/**
 * Link version 1, frozen: the log, update and host-answered channels.
 *
 * Written out as concrete types, copied from the shapes the app resolved when link version 1 was cut. It never
 * references the living types, so a change to a handler cannot move it. Do not edit this file to match a changed
 * handler: a change that breaks it needs a new LINK_VERSION and a new `contract/v<N>/` (see protocol.ts for the
 * rule). `tests/remote/contractV1.test.ts` checks the living types against it.
 */

import type { LogEntryV1, UpdateSummaryV1 } from './shapesConfig';

export type AppChannelsV1 = {
    'can-auto-update': {
        args: [];
        result: { success: true; canAutoUpdate: boolean } | { success: false; canAutoUpdate: boolean };
    };
    'check-for-updates': {
        args: [];
        result: { success: true; updateInfo: null | UpdateSummaryV1 } | { success: false; error: string };
    };
    'cleanup-stale-metadata': {
        args: [activeChallengeIds: (string | number)[]];
        result: { success: false; error: string } | { success: false; error: 'invalid-args' } | { success: true };
    };
    'clear-skip-version': { args: []; result: { success: false; error: string } | { success: true } };
    'get-log-backlog': { args: []; result: LogEntryV1[] };
    'get-releases-url': { args: []; result: { success: true; url: string } };
    'skip-update-version': { args: []; result: { success: false; error: string } | { success: true } };
    'start-log-stream': { args: []; result: { success: false; error: string } | { success: true } };
    'stop-log-stream': { args: []; result: { success: false; error: string } | { success: true } };
};
